import { useState } from 'react';
import { getStoredCustomRocks, saveCustomRocks } from '../../lib/adminData';

export default function AddRockForm({ onRockAdded }) {
  const [formData, setFormData] = useState({
    name: '', price: '', shippingFee: '', weight: '', height: '', width: '', length: '', volume: '', imgdir: ''
  });

  const handleChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });

  const handleSubmit = (e) => {
    e.preventDefault();
    const newRock = {
      name: formData.name,
      price: Number(formData.price),
      'shipping-fee': Number(formData.shippingFee),
      weight: Number(formData.weight),
      height: Number(formData.height),
      width: Number(formData.width),
      length: Number(formData.length),
      volume: Number(formData.volume),
      imgdir: formData.imgdir || 'assets/images/attachment.gif'
    };

    const customRocks = getStoredCustomRocks();
    customRocks.push(newRock);
    saveCustomRocks(customRocks);

    onRockAdded(newRock);
    alert("¡Roca guardada exitosamente!");
    setFormData({ name: '', price: '', shippingFee: '', weight: '', height: '', width: '', length: '', volume: '', imgdir: '' });
  };

  return (
    <form onSubmit={handleSubmit} className="bg-black p-4 rounded-4 text-white">
      <h4 className="mb-3">Añadir Nueva Roca</h4>
      <div className="row g-3">
        <div className="col-md-6"><input name="name" className="form-control bg-dark text-white border-secondary" placeholder="Nombre" value={formData.name} onChange={handleChange} required /></div>
        <div className="col-md-3"><input name="price" type="number" className="form-control bg-dark text-white border-secondary" placeholder="Precio" value={formData.price} onChange={handleChange} required /></div>
        <div className="col-md-3"><input name="shippingFee" type="number" className="form-control bg-dark text-white border-secondary" placeholder="Envío" value={formData.shippingFee} onChange={handleChange} required /></div>
        <div className="col-md-3"><input name="weight" type="number" className="form-control bg-dark text-white border-secondary" placeholder="Peso (g)" value={formData.weight} onChange={handleChange} required /></div>
        <div className="col-md-3"><input name="height" type="number" className="form-control bg-dark text-white border-secondary" placeholder="Altura (mm)" value={formData.height} onChange={handleChange} required /></div>
        <div className="col-md-3"><input name="width" type="number" className="form-control bg-dark text-white border-secondary" placeholder="Anchura (mm)" value={formData.width} onChange={handleChange} required /></div>
        <div className="col-md-3"><input name="length" type="number" className="form-control bg-dark text-white border-secondary" placeholder="Longitud (mm)" value={formData.length} onChange={handleChange} required /></div>
        <div className="col-md-3"><input name="volume" type="number" className="form-control bg-dark text-white border-secondary" placeholder="Volumen" value={formData.volume} onChange={handleChange} required /></div>
        <div className="col-12"><input name="imgdir" className="form-control bg-dark text-white border-secondary" placeholder="Ruta de imagen (ej: assets/1.png)" value={formData.imgdir} onChange={handleChange} /></div>
      </div>
      <button type="submit" className="btn btn-light mt-3 fw-bold">Guardar Roca en Inventario</button>
    </form>
  );
}

import { getStoredCustomRocks, getDeletedRockNames, saveCustomRocks, saveDeletedRockNames } from '../../lib/adminData';

export default function RocksTable({ allRocks, setAllRocks }) {
  const handleDelete = (index) => {
    const targetRock = allRocks[index];
    if (!targetRock) return;

    if (window.confirm(`¿Está seguro de que desea eliminar la roca "${targetRock.name}"?`)) {
      // Check if it's a custom rock or a default one
      const customRocks = getStoredCustomRocks();
      const isCustom = customRocks.some(r => r.name === targetRock.name);

      if (isCustom) {
        const updatedCustom = customRocks.filter(r => r.name !== targetRock.name);
        saveCustomRocks(updatedCustom);
      } else {
        const deletedNames = getDeletedRockNames();
        deletedNames.push(targetRock.name);
        saveDeletedRockNames(deletedNames);
      }

      // Update local state
      const newRocks = [...allRocks];
      newRocks.splice(index, 1);
      setAllRocks(newRocks);
    }
  };

  const priceFormatter = new Intl.NumberFormat('es-CL', { style: 'currency', currency: 'CLP' });

  return (
    <div className="table-responsive">
      <table className="table table-dark table-striped">
        <thead>
          <tr>
            <th>ID</th><th>Vista</th><th>Nombre</th><th>Precio</th><th>Peso (g)</th><th>Dimensiones</th><th>Volumen</th><th>Acciones</th>
          </tr>
        </thead>
        <tbody>
          {allRocks.length === 0 ? (
            <tr><td colSpan="8" className="text-center text-muted">No hay rocas disponibles.</td></tr>
          ) : (
            allRocks.map((rock, index) => (
              <tr key={`${rock.name}-${index}`}>
                <td><code>#{index}</code></td>
                <td><img src={rock.imgdir} alt={rock.name} style={{ width: '32px', height: '32px', objectFit: 'contain' }} /></td>
                <td><strong>{rock.name}</strong></td>
                <td>{priceFormatter.format(rock.price)}</td>
                <td>{rock.weight} g</td>
                <td>{rock.height} × {rock.width} × {rock.length} mm</td>
                <td>{rock.volume} mm³</td>
                <td>
                  <button className="btn btn-sm btn-danger" onClick={() => handleDelete(index)}>Eliminar</button>
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
}

import { MOCK_SALES } from '../../lib/adminData';

export default function SalesTable() {
  const storedReceipt = localStorage.getItem('pieca_receipt');
  let salesList = [...MOCK_SALES];

  if (storedReceipt) {
    try {
      const parsed = JSON.parse(storedReceipt);
      salesList.unshift({
        id: "BOL-" + Math.floor(10000 + Math.random() * 90000),
        date: new Date(parsed.date).toLocaleString('es-CL'),
        customer: "Cliente Actual (Sesión)",
        items: `${parsed.items.length} tipo(s) de roca`,
        total: parsed.total,
        status: parsed.status || "Pendiente"
      });
    } catch (e) { console.error(e); }
  }

  const priceFormatter = new Intl.NumberFormat('es-CL', { style: 'currency', currency: 'CLP' });

  return (
    <div className="table-responsive">
      <table className="table table-dark table-striped">
        <thead>
          <tr><th>Nº Boleta</th><th>Fecha</th><th>Cliente</th><th>Productos</th><th>Total</th><th>Estado</th></tr>
        </thead>
        <tbody>
          {salesList.map((sale, i) => (
            <tr key={i}>
              <td><code>{sale.id}</code></td>
              <td>{sale.date}</td>
              <td>{sale.customer}</td>
              <td>{sale.items}</td>
              <td>{priceFormatter.format(sale.total)}</td>
              <td><span className={`badge ${sale.status === 'Completado' ? 'bg-success' : 'bg-warning text-dark'}`}>{sale.status}</span></td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

import { MOCK_USERS } from '../../lib/adminData';

export default function UsersTable() {
  const storedUser = localStorage.getItem('pieca_user');
  let usersList = [...MOCK_USERS];

  if (storedUser) {
    try {
      const parsed = JSON.parse(storedUser);
      if (parsed.email && !usersList.some(u => u.email === parsed.email)) {
        usersList.unshift({
          rut: parsed.rut || "Sin RUT",
          name: parsed.name || "Usuario Activo",
          username: parsed.username || "usuario_demo",
          email: parsed.email,
          role: "Cliente"
        });
      }
    } catch (e) { console.error(e); }
  }

  return (
    <div className="table-responsive">
      <table className="table table-dark table-striped">
        <thead>
          <tr><th>RUT</th><th>Nombre Completo</th><th>Usuario</th><th>Email</th><th>Rol</th></tr>
        </thead>
        <tbody>
          {usersList.map((user, i) => (
            <tr key={i}>
              <td><code>{user.rut}</code></td>
              <td>{user.name}</td>
              <td>@{user.username}</td>
              <td>{user.email}</td>
              <td><span className={`badge ${user.role === 'Administrador' ? 'bg-success' : 'bg-warning text-dark'}`}>{user.role}</span></td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

