import { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router';
import RockCard from './RockCard';

const CARD_WIDTH = 250;
const GAP = 30;
const STEP = CARD_WIDTH + GAP;

export default function Carousel({ items = [] }) {
  const [activeIndex, setActiveIndex] = useState(0);
  const containerRef = useRef(null);
  const [containerWidth, setContainerWidth] = useState(0);

  useEffect(() => {
    if (!containerRef.current) return;
    const updateWidth = () => setContainerWidth(containerRef.current.offsetWidth);
    updateWidth();
    const observer = new ResizeObserver(updateWidth);
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (!items.length) return;
    const interval = setInterval(() => {
      setActiveIndex((prev) => (prev + 1) % items.length);
    }, 4000);
    return () => clearInterval(interval);
  }, [items.length]);

  const handlePrev = () => setActiveIndex((prev) => (prev === 0 ? items.length - 1 : prev - 1));
  const handleNext = () => setActiveIndex((prev) => (prev + 1) % items.length);

  const trackOffset = containerWidth / 2 - CARD_WIDTH / 2 - activeIndex * STEP;

  return (
    <section className="container my-5">
      <div className="d-flex justify-content-between align-items-center mb-4 px-3">
        <h2 className="m-0 text-black fs-3">&bull; Nuestras piedras.</h2>
        <Link to="/catalog" className="btn btn-dark rounded-pill px-4">Ver todo</Link>
      </div>

      <div ref={containerRef} className="position-relative overflow-hidden py-5 w-100">
        <button
          className="btn btn-link text-black position-absolute top-50 start-0 translate-middle-y z-3 fs-1 text-decoration-none"
          onClick={handlePrev}
          aria-label="Previous item"
          style={{ left: '10px' }}
        >&#8249;</button>

        <button
          className="btn btn-link text-black position-absolute top-50 end-0 translate-middle-y z-3 fs-1 text-decoration-none"
          onClick={handleNext}
          aria-label="Next item"
          style={{ right: '10px' }}
        >&#8250;</button>

        <div
          className="d-flex align-items-center"
          style={{
            transform: `translateX(${trackOffset}px)`,
            transition: 'transform 0.5s cubic-bezier(0.25, 1, 0.5, 1)',
            gap: `${GAP}px`
          }}
        >
          {items.map((item, index) => {
            const absDiff = Math.abs(index - activeIndex);
            const cardState = absDiff === 0 ? 'active' : absDiff === 1 ? 'side' : 'far';

            return (
              <div
                key={item.id ?? index}
                style={{ width: CARD_WIDTH, flexShrink: 0 }}
                onClick={() => setActiveIndex(index)}
              >
                <RockCard item={item} index={index} cardState={cardState} />
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}

import React from 'react';
import { createRoot } from 'react-dom/client';
import { BrowserRouter } from 'react-router';
import Carousel from './Carousel';
import rocksData from '../data/rocks.json';

describe('Carousel.jsx', () => {
  let container, root;
  beforeEach(() => {
    container = document.createElement('div');
    document.body.appendChild(container);
    root = createRoot(container);
  });
  afterEach(() => { root.unmount(); container.remove(); });

  it('renderiza las tarjetas con estado active/side/far', async () => {
    root.render(<BrowserRouter><Carousel items={rocksData.slice(0, 3)} /></BrowserRouter>);
    await new Promise(r => setTimeout(r, 50));
    expect(container.querySelectorAll('.carousel-card.active').length).toBeGreaterThan(0);
    expect(container.querySelectorAll('.carousel-card.side').length).toBeGreaterThan(0);
    expect(container.querySelectorAll('.carousel-card.far').length).toBeGreaterThan(0);
  });

  it('botón prev vuelve al último item', async () => {
    root.render(<BrowserRouter><Carousel items={rocksData.slice(0, 3)} /></BrowserRouter>);
    await new Promise(r => setTimeout(r, 50));
    const prev = container.querySelector('[aria-label="Previous item"]');
    prev.click();
    await new Promise(r => setTimeout(r, 50));
    // After prev from 0, activeIndex should be items.length - 1 = 2
    // The third card should now be active
    const cards = container.querySelectorAll('.carousel-card');
    expect(cards[2].classList.contains('active')).toBe(true);
  });

  it('botón next avanza al siguiente item', async () => {
    root.render(<BrowserRouter><Carousel items={rocksData.slice(0, 3)} /></BrowserRouter>);
    await new Promise(r => setTimeout(r, 50));
    const next = container.querySelector('[aria-label="Next item"]');
    next.click();
    await new Promise(r => setTimeout(r, 50));
    const cards = container.querySelectorAll('.carousel-card');
    expect(cards[1].classList.contains('active')).toBe(true);
  });

  it('no rompe con items vacío', async () => {
    root.render(<BrowserRouter><Carousel items={[]} /></BrowserRouter>);
    await new Promise(r => setTimeout(r, 50));
    expect(container.querySelectorAll('.carousel-card').length).toBe(0);
  });
});

