    width: 40% !important;
  }
}

.fade-in {
  opacity: 0;
  animation: fadeIn 2.5s ease-in forwards;
}

@keyframes fadeIn {
  0% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}

.text-black {
  color: black;
}
.text-white {
  color: white;
}

.carousel-card {
  width: 250px;
  height: 280px;
  border-radius: 12px;
  background-color: #1a1a1a;
  cursor: pointer;
  border: none;
  flex-shrink: 0;
  overflow: hidden;
  box-sizing: border-box;
  transition: transform 0.5s ease, opacity 0.5s ease, background-color 0.5s ease;
}

.carousel-card.active {
  transform: scale(1);
  opacity: 1;
  background-color: #2a2a2a;
  z-index: 2;
  pointer-events: auto;
}

.carousel-card.side {
  transform: scale(0.8);
