    it('acepta RUT con DV K', () => expect(validateRUT('12.345.670-K')).toBe(true));
    it('acepta RUT con DV 0', () => expect(validateRUT('12.345.675-0')).toBe(true));
    it('acepta RUT sin formato', () => expect(validateRUT('123456785')).toBe(true));
